+        this.creationThread = Thread.currentThread();
+        this.wrapper = wrapper;
+    }
+
+    final boolean assertAccessingThread() {
+        assert creationThread == Thread.currentThread()
+            : "created by [" + creationThread + "] != current thread [" + Thread.currentThread() + "]";
+        return true;
+    }
